parameters.jsCode:
// Pass the synthesized WAV through with a small summary
const item = $input.first();
const audio = item.binary && item.binary.data ? item.binary.data : null;
const source = $('TTS Webhook Trigger').first().json;
const req = source.body || source;

return [{
  json: {
    success: audio !== null,
    speaker: req.voice || 'af_heart',
    duration_seconds: 0,
    audio_size_bytes: audio && audio.fileSize ? audio.fileSize : 0,
    channel: req.channel || '#general',
    timestamp: new Date().toISOString()
  },
  binary: audio ? { data: audio } : {}
}];
